const $=s=>document.querySelector(s);const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;let paused=reduced;const menu=$('#menu'),menuButton=$('#menuButton');function closeMenu(){menu.hidden=true;menuButton.setAttribute('aria-expanded','false');document.body.style.overflow=''}menuButton.addEventListener('click',()=>{const open=menu.hidden;menu.hidden=!open;menuButton.setAttribute('aria-expanded',String(open));document.body.style.overflow=open?'hidden':'';if(open)menu.querySelector('a').focus()});document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeMenu();menuButton.focus()}if(!menu.hidden&&e.key==='Tab'){const links=[menuButton,...menu.querySelectorAll('a')];if(e.shiftKey&&document.activeElement===links[0]){e.preventDefault();links.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===links.at(-1)){e.preventDefault();links[0].focus()}}});menu.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{closeMenu();const target=$(a.hash);target.setAttribute('tabindex','-1');target.focus({preventScroll:true})}));
