const cursor=$('#cursor');let px=.5,py=.5;addEventListener('pointermove',e=>{px=e.clientX/innerWidth;py=e.clientY/innerHeight;if(e.pointerType==='mouse'&&!paused){cursor.style.opacity='1';cursor.style.transform=`translate(${e.clientX-12}px,${e.clientY-12}px)`}});document.addEventListener('pointerleave',()=>cursor.style.opacity='0');
const canvas=$('#signal'),ctx=canvas.getContext('2d');let w=600,h=600,visible=true;function resize(){const rect=canvas.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,1.5);w=rect.width;h=rect.height;canvas.width=w*dpr;canvas.height=h*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);if(paused)draw(0)}addEventListener('resize',resize);new IntersectionObserver(entries=>visible=entries[0].isIntersecting).observe(canvas);const rings=32,points=72;
function draw(t){if(!ctx)return;ctx.clearRect(0,0,w,h);const time=paused?.5:t*.00016;const scale=Math.min(w,h)*.33;const cx=w*.51+(px-.5)*12,cy=h*.48+(py-.5)*10;const angle=time*.5;function project(a,b){const radius=1.05+.27*Math.cos(3*b+time*2);let x=radius*Math.cos(a),y=radius*Math.sin(a),z=.4*Math.sin(3*b+time*2)+.3*Math.cos(b);x*=Math.cos(b)*.42+.73;y*=Math.cos(b)*.42+.73;const xx=x*Math.cos(angle)-z*Math.sin(angle),zz=x*Math.sin(angle)+z*Math.cos(angle);const yy=y*.62-zz*.65;const depth=y*.65+zz*.62;const p=2.8/(3.4-depth*.32);return[cx+xx*scale*p,cy+yy*scale*p,depth]}
for(let j=0;j<rings;j++){const b=j/rings*Math.PI*2;ctx.beginPath();for(let i=0;i<=points;i++){const a=i/points*Math.PI*2,p=project(a,b);if(i===0)ctx.moveTo(p[0],p[1]);else ctx.lineTo(p[0],p[1])}ctx.strokeStyle=j%4===0?'rgba(194,250,56,.55)':'rgba(140,184,43,.22)';ctx.lineWidth=j%4===0?.8:.5;ctx.stroke()}for(let i=0;i<points;i+=2){ctx.beginPath();for(let j=0;j<=rings;j++){const p=project(i/points*Math.PI*2,j/rings*Math.PI*2);if(!j)ctx.moveTo(p[0],p[1]);else ctx.lineTo(p[0],p[1])}ctx.strokeStyle='rgba(174,230,55,.17)';ctx.lineWidth=.6;ctx.stroke()}
ctx.strokeStyle='#c2fa3838';ctx.lineWidth=.6;const corners=[[cx-scale*1.3,cy-scale],[cx+scale*1.3,cy-scale],[cx-scale*1.3,cy+scale],[cx+scale*1.3,cy+scale]];corners.forEach(([x,y],i)=>{const sx=i%2===0?1:-1,sy=i<2?1:-1;ctx.beginPath();ctx.moveTo(x,y+sy*15);ctx.lineTo(x,y);ctx.lineTo(x+sx*15,y);ctx.stroke()});ctx.fillStyle='#c2fa38';[[.14,.32],[.78,.2],[.9,.65],[.28,.83]].forEach(([x,y],i)=>{const dy=paused?0:Math.sin(time*4+i)*8;ctx.fillRect(w*x,h*y+dy,2,2)});}
